  'Référentiel Géographique Commun RDC (OCHA, 2019) via geoBoundaries gbOpen COD ADM2', 'CC BY 3.0 IGO', now()
from public.geographic_units u
where u.slug = 'yahuma' and u.type_key = 'territoire'
on conflict (unit_id) do update set boundary = excluded.boundary, source = excluded.source,
  license = excluded.license, verified_at = excluded.verified_at;

-- Province de la Tshopo : union des limites de ses unités de premier niveau.
insert into public.geographic_boundaries (unit_id, boundary, source, license, verified_at)
select p.id,
  gis.st_multi(gis.st_collectionextract(gis.st_makevalid(gis.st_union(b.boundary::gis.geometry)), 3))::gis.geography,
  'Union des limites de Kisangani et des 7 territoires — Référentiel Géographique Commun RDC (OCHA, 2019) via geoBoundaries gbOpen COD ADM2',
  'CC BY 3.0 IGO', now()
from public.geographic_units p
join public.geographic_units c on c.parent_id = p.id
join public.geographic_boundaries b on b.unit_id = c.id
where p.slug = 'tshopo' and p.type_key = 'province'
group by p.id
on conflict (unit_id) do update set boundary = excluded.boundary, source = excluded.source,
  license = excluded.license, verified_at = excluded.verified_at;

select public.refresh_unit_centers();